targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	 /**
     * Create the URL to redirect to, when we click on the ref column, in the reusable results page
     * requestSysId: RequestId of the evaluation, from the request table
     * resultSysId: ResultSysId of the evaluation, from the results table
     * */
    const cellMetaData = event?.payload?.cell?.metadata;
    const resultSysId = cellMetaData?.referenceSysId;
    const requestSysId = api?.context?.props?.requestId;
    const viewType = api?.context?.props?.viewType;
    // params need to be included here, when we try render a page from a reusable entity
    const extUrl = "now/access-management/logs/" + requestSysId + "/" + resultSysId + "/params/view-type/" + viewType;
    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        // Route to another page, the page within AA, not in separate tab, the page that will open will render the viewTypes accordingly
        external: {
            url: extUrl,
            target: "_self"
        },
        navigationOptions: null
    };
})

